import (
	context "context"
	fern "github.com/go-date-containers/fern"
	fernclient "github.com/go-date-containers/fern/client"
)

client := fernclient.NewClient()
response, err := client.Loans.ListLoansByDate(
	context.TODO(),
	&fern.ListLoansByDateRequest{
		AsOf: fern.MustParseDate(
			"2023-01-15",
		),
		Page: &fern.PageRequest{
			Number: fern.Int(
				1,
			),
			Size: fern.Int(
				1,
			),
		},
	},
)

